if (window.soapController) {
	return {hidden: true};
}

const { pageSize, maxResults, pageNumber } = options.getState().pagination;
const isInvalidPaginationInputs = [pageSize, maxResults, pageNumber].some(item => item === null);

return {
	hidden: false,
	disabled: isInvalidPaginationInputs
};
